Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

// Function to generate the Fibonacci sequence
vector<int> fibonacci(int n, int a, int b) {
    if (n == 0) {
        return vector<int>();
    }

    vector<int> result = fibonacci(n - 1, b, a + b);
    result.push_back(a);

    return result;
}

int main() {
    string input;
    int n, a, b;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);

    if (!(iss >> a >> b)) {
        throw runtime_error("Invalid input");
    }

    if (a < 0 || b < 0) {
        throw runtime_error("Both integers must be non-negative");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    if (n <= 0) {
        throw runtime_error("The number of sequence elements must be positive");
    }

    try {
        vector<int> sequence = fibonacci(n, a, b);
        cout << "Fibonacci sequence: ";
        for (int i = 0; i < sequence.size(); i++) {
            cout << sequence[i] << ", ";
        }
        cout << endl;
    } catch (runtime_error& e) {
        cerr << "Error: " << e.what() << endl;
    }

    return 0;
}
```

This program prompts the user to enter the first two integers and the number of sequence elements to generate. It then generates the Fibonacci sequence using the `fibonacci` function and outputs the generated sequence. The program includes error handling for invalid inputs, such as non-numeric inputs or negative numbers.

