To calculate the distance between two points on the Earth's surface, considering it as an ellipsoid, you can use the following MATLAB code:

```matlab
function distance = ellipsoidal_distance(lat1, lon1, lat2, lon2)
    % Convert latitudes and longitudes from degrees to radians
    lat1 = deg2rad(lat1);
    lon1 = deg2rad(lon1);
    lat2 = deg2rad(lat2);
    lon2 = deg2rad(lon2);

    % Define the Earth's semi-major and semi-minor axes in meters
    a = 6378137; % Earth's semi-major axis
    b = 6356752.3142; % Earth's semi-minor axis

    % Calculate the Earth's flattening and eccentricity squared
    f = (a-b)/a;
    e2 = 2*f - f^2;

    % Calculate the radii of curvature in the prime vertical at both points
    N1 = a / sqrt(1 - e2 * sin(lat1)^2);
    N2 = a / sqrt(1 - e2 * sin(lat2)^2);

    % Calculate the Cartesian coordinates of both points
    x1 = (N1 + h1) * cos(lat1) * cos(lon1);
    y1 = (N1 + h1) * cos(lat1) * sin(lon1);
    z1 = ((1 - e2) * N1 + h1) * sin(lat1);
    x2 = (N2 + h2) * cos(lat2) * cos(lon2);
    y2 = (N2 + h2) * cos(lat2) * sin(lon2);
    z2 = ((1 - e2) * N2 + h2) * sin(lat2);

    % Calculate the distance between the two points in meters
    d = sqrt((x1 - x2)^2 + (y1 - y2)^2 + (z1 - z2)^2);
end

