Create a new C# script called "MusicVisualizer" and add the following code:

```csharp
using UnityEngine;
using UnityEngine.Audio;
using UnityEngine.Audio.Analysis;

public class MusicVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public float frequencyRange = 0.5f; // Adjust this value to control the sensitivity of the visualizer
    public GameObject visualizerObject;

    private AudioAnalyzer audioAnalyzer;
    private float[] spectrumData;

    void Start()
    {
        audioAnalyzer = gameObject.AddComponent<AudioAnalyzer>();
        audioAnalyzer.SetUp(audioSource);
        audioAnalyzer.Start();

        spectrumData = new float[audioAnalyzer.frequencyBins];
    }

    void Update()
    {
        audioAnalyzer.GetSpectrumData(spectrumData);

        // Process the spectrum data to generate the visualizer
        // You can use various algorithms for this, such as FFT or STFT
        // For simplicity, let's assume we're using a simple thresholding algorithm
        bool[] isPeak = new bool[spectrumData.Length];
        for (int i = 0; i < spectrumData.Length; i++)
        {
            if (spectrumData[i] > frequencyRange)
            {
                isPeak[i] = true;
            }
        }

        // Update the visualizer object based on the peak detection results
        visualizerObject.SetActive(true);
        visualizerObject.transform.localScale = Vector3.one * isPeak.Sum();
    }
}
```

