1. Create an HTML file and add the necessary structure.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Prime Numbers</title>
    <script src="script.js"></script>
</head>
<body>
    <h1>Prime Numbers</h1>
    <ul id="primeNumbers"></ul>
    <p id="product"></p>
</body>
</html>
```

2. Create a JavaScript file (script.js) and define the functions to display the prime numbers and calculate their product.

```javascript
// Function to display the prime numbers
function displayPrimeNumbers() {
    const primeNumbers = [3, 7, 13, 19];
    const ulElement = document.getElementById('primeNumbers');

    ulElement.innerHTML = '';

    primeNumbers.forEach(number => {
        const liElement = document.createElement('li');
        liElement.textContent = number;
        ulElement.appendChild(liElement);
    });
}

// Function to calculate the product of the prime numbers
function calculateProduct() {
    const primeNumbers = [3, 7, 13, 19];
    let product = 1;

    primeNumbers.forEach(number => {
        product *= number;
    });

