// Component
import React, { useState } from 'react';

const ManageRegistrationScreen = () => {
  const [registrations, setRegistrations] = useState([]);

  const checkMNPStatusAPI = async (phoneNo, index) => {
    try {
      const response = await fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
        headers: {
          Authorization: `Bearer ${user.getAccessToken()}`,
        },
        method: 'GET',
      });

      const jsonResponse = await response.json();
      const status = jsonResponse.status;

      // Update the registration with the MNP status
      const updatedRegistration = { ...registrations[index], mnpStatus: status };
      const newRegistrations = [...registrations];
      newRegistrations[index] = updatedRegistration;
      setRegistrations(newRegistrations);
    } catch (error) {
      console.error('Error checking MNP status:', error);
    }
  };

  return (
    <div>
      {/* Render the registrations list */}
    </div>
  );
};

export default ManageRegistrationScreen;
